import java.io.BufferedReader
import java.io.InputStreamReader

var solve: String = ""
var s: String = ""
var N: Int = 0

fun Check() {

    if (solve[0] == '.') {
        solve = solve.substring(1)
        solve = "dot" + solve
    } else if (solve[0] == '@') {
        solve = solve.substring(1)
        solve = "at" + solve
    }

    if (solve[solve.length - 1] == '.') {
        solve = solve.substring(0, solve.length - 1)
        solve += "dot"
    } else if (solve[solve.length - 1] == '@') {
        solve = solve.substring(0, solve.length - 1)
        solve += "at"
    }

}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))

    s = br.readText().trim()

    N = s.length

    solve = ""

    var I = 0
    while (I < N) {

        if (I + 3 <= N) {
            if (s.substring(I, I + 3) == "dot") {
                solve += "."
                I += 2
            } else {
                if (I + 2 <= N) {
                    if (s.substring(I, I + 2) == "at") {
                        solve += "@"
                        I += 1
                    } else solve += s[I]
                } else solve += s[I]
            }
        } else if (I + 2 <= N) {
            if (s.substring(I, I + 2) == "at") {
                solve += "@"
                I += 1
            } else solve += s[I]
        } else solve += s[I]

        ++I
    }

    Check()

    var cont = 0

    for (J in 0 until solve.length) {

        if (solve[J] == '@') ++cont

    }

    val sb = StringBuilder()

    if (cont == 1) {
        sb.append(solve)
        sb.append('\n')
    } else {

        var ok = true

        for (J in 0 until solve.length) {

            if (solve[J] == '@') {
                if (ok) {
                    sb.append('@')
                    ok = false
                } else {
                    sb.append("at")
                }
                continue
            }
            sb.append(solve[J])
        }
        sb.append('\n')
    }

    print(sb)
}
